use super::*;
use std::sync::{Mutex,atomic::{AtomicBool,AtomicUsize,Ordering}};
use crate::{mcrf_bs_session::{Session as Shared,Dependencies},mcrf_bs_dns_transport::{SocketPolicy,Failure as SocketFailure,Direction},mcrf_bs_udp_dispatch::{Reply,Task,Failure as UdpFailure}};
struct Sockets(AtomicUsize);impl SocketPolicy for Sockets{fn prepare(&self,protocol:u8,_:i32,_:u16,_:SocketAddr,direction:Direction)->Result<Box<dyn Send>,SocketFailure>{assert_eq!(protocol,17);assert_eq!(direction,Direction::Direct);self.0.fetch_add(1,Ordering::SeqCst);Ok(Box::new(()))}}
struct NoTunReply;impl Reply for NoTunReply{fn write<'a>(&'a self,_:SocketAddr,_:SocketAddr,_:&'a [u8],_:&'a CancellationToken)->Task<'a,()>{Box::pin(async{Err(UdpFailure::Reply)})}}
async fn run(dns_mode:bool,changed:bool){tokio::time::timeout(Duration::from_secs(10),async{
 let echo=UdpSocket::bind("127.0.0.1:0").await.unwrap();let target=echo.local_addr().unwrap();let client=UdpSocket::bind("127.0.0.1:0").await.unwrap();let source=client.local_addr().unwrap();
 let(tx,mut queries)=mpsc::unbounded_channel();let owner=Arc::new(crate::mcrf_bs_owner::Broker::new(42,Arc::new(move|s|tx.send(s.to_owned()).map_err(|_|crate::mcrf_bs_owner::Failure::Pipe))).unwrap());let sockets=Arc::new(Sockets(AtomicUsize::new(0)));
 let controls=if dns_mode{serde_json::json!([{"beforeRule":0,"operation":{"action":"hijack-dns"}}])}else{serde_json::json!([{"beforeRule":0,"operation":{"action":"route-options","udp_timeout":"50ms"}}])};
 let document=serde_json::to_vec(&serde_json::json!({"schema":1,"policy":{"schema":1,"defaultTarget":"direct","rules":[]},"dns":{"servers":[{"type":"hosts","tag":"h","predefined":{"Owned.Invalid":"127.0.0.1","answer.invalid":"192.0.2.9"}}],"final":"h"},"controls":controls,"routeOptions":{},"tunInbounds":[],"dnsDialers":{}})).unwrap();
 let session=Arc::new(Shared::prepare(&document,Dependencies{generation:42,capacity:16,owner:owner.clone(),physical:1,hosts:HashMap::new(),excluded:Vec::new(),sockets:sockets.clone(),underlay:crate::mcrf_bs_dns_handler::Underlay{kind:"wifi".into(),expensive:false,constrained:false,ssid:String::new(),bssid:String::new()},retire:Arc::new(|_|Ok(())),connector:Arc::new(crate::mcrf_bs_udp_transport::Selected{policy:sockets.clone()}),reply:Arc::new(NoTunReply)},&CancellationToken::new()).unwrap());
 let limits=Arc::new(Limits::new());let handler=crate::mcrf_bs_proxy_backend::mixed_handler_with_limits(session.tcp.clone(),session.udp.clone(),limits.clone());let mut plan=mcrf_bs_routing_policy::listeners::parse(Some(&serde_json::json!([{"type":"mixed","tag":"owned","listen":"127.0.0.1","listen_port":10808}]))).unwrap().remove(0);plan.address.set_port(0);
 let parent=CancellationToken::new();let group=crate::mcrf_bs_proxy_listener::Group::start(42,vec![plan],4,handler,Arc::new(|_|{}),&parent).unwrap();let tcp_local=group.addresses()[0];let mut control=TcpStream::connect(tcp_local).await.unwrap();let tcp_source=control.local_addr().unwrap();let udp_local=Arc::new(Mutex::new(None));let local=udp_local.clone();let denied=Arc::new(AtomicBool::new(false));let deny=denied.clone();let broker=owner.clone();let udp_queries=Arc::new(AtomicUsize::new(0));let count=udp_queries.clone();
 let answers=tokio::spawn(async move{while let Some(query)=queries.recv().await{let f=query.split_whitespace().collect::<Vec<_>>();assert_eq!(f[4],"127.0.0.1");assert_eq!(f[6],"127.0.0.1");let udp=f[3]=="17";if udp{assert_eq!(f[5],source.port().to_string());assert_eq!(f[7],local.lock().unwrap().unwrap_or(0).to_string());count.fetch_add(1,Ordering::SeqCst);}else{assert_eq!(f[3],"6");assert_eq!(f[5],tcp_source.port().to_string());assert_eq!(f[7],tcp_local.port().to_string());}let uid=if udp&&deny.load(Ordering::SeqCst){10002}else{10001};broker.respond(&format!("BS_OWNER|42|{}|{uid}|W10=",f[2])).unwrap();}});
 control.write_all(&[5,1,0,5,3,0,1,0,0,0,0,0,0]).await.unwrap();let mut hello=[0;2];control.read_exact(&mut hello).await.unwrap();assert_eq!(hello,[5,0]);let mut ack=[0;10];control.read_exact(&mut ack).await.unwrap();assert_eq!(&ack[..4],&[5,0,0,1]);let local=SocketAddr::from(([ack[4],ack[5],ack[6],ack[7]],u16::from_be_bytes([ack[8],ack[9]])));*udp_local.lock().unwrap()=Some(local.port());
 if changed{denied.store(true,Ordering::SeqCst);let bytes=protocol::datagram_reply(&Destination::Address(target),b"denied").unwrap();client.send_to(&bytes,local).await.unwrap();let mut b=[0;64];assert!(tokio::time::timeout(Duration::from_millis(100),echo.recv_from(&mut b)).await.is_err());assert_eq!(sockets.0.load(Ordering::SeqCst),0);}
 else if dns_mode{let query=mcrf_bs_routing_policy::dns_wire::query(1,"answer.invalid",1).unwrap();let dest=Destination::Address("192.0.2.53:5353".parse().unwrap());client.send_to(&protocol::datagram_reply(&dest,&query).unwrap(),local).await.unwrap();let mut bytes=[0;2048];let(n,_)=client.recv_from(&mut bytes).await.unwrap();let(reply_from,payload)=protocol::datagram(&bytes[..n]).await.unwrap();assert!(reply_from==dest);assert_eq!(mcrf_bs_routing_policy::dns_wire::addresses(&query,payload).unwrap()[0].ip,"192.0.2.9".parse::<std::net::IpAddr>().unwrap());assert_eq!(sockets.0.load(Ordering::SeqCst),0);assert!(udp_queries.load(Ordering::SeqCst)>=4);}
 else{for (index,payload)in [b"owned".as_slice(),b"".as_slice(),b"again".as_slice()].iter().enumerate(){let dest=if index==2{Destination::Domain("Owned.Invalid".into(),target.port())}else{Destination::Address(target)};client.send_to(&protocol::datagram_reply(&dest,payload).unwrap(),local).await.unwrap();let mut bytes=[0;2048];let(n,peer)=echo.recv_from(&mut bytes).await.unwrap();assert_eq!(&bytes[..n],*payload);echo.send_to(&bytes[..n],peer).await.unwrap();let(n,_)=client.recv_from(&mut bytes).await.unwrap();let(reply_from,body)=protocol::datagram(&bytes[..n]).await.unwrap();assert!(reply_from==dest);assert_eq!(body,*payload);}}
 control.shutdown().await.unwrap();group.close().await.unwrap();assert!(!parent.is_cancelled());assert_eq!(limits.flows.available_permits(),64);assert_eq!(limits.bytes.available_permits(),2*1024*1024);let _rebound=UdpSocket::bind(local).await.unwrap();owner.close();answers.abort();let _=answers.await;
 }).await.unwrap()}
#[tokio::test]async fn shared_udp_routes_domain_and_literal_preserves_zero_and_closes_with_control(){run(false,false).await}
#[tokio::test]async fn udp_dns_uses_same_engine_and_actual_client_owner(){run(true,false).await}
#[tokio::test]async fn unrelated_udp_owner_cannot_forward_using_tcp_identity(){run(false,true).await}
#[test]fn queued_datagram_holds_memory_budget_until_capture_is_dropped(){let limits=Limits::new();let permit=limits.bytes.clone().try_acquire_many_owned(7).unwrap();let packet=Datagram::budgeted(vec![0;7],permit).unwrap();let mut saved=Captured::default();saved.push(packet).unwrap();assert_eq!(limits.bytes.available_permits(),2*1024*1024-7);drop(saved);assert_eq!(limits.bytes.available_permits(),2*1024*1024);}
